begin;
create function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'assertion failed: %',message; end if; end; $$;
insert into auth.users(id) values('28000600-0000-4000-8000-000000000001'),('28000600-0000-4000-8000-000000000002'),('28000600-0000-4000-8000-000000000003');
insert into public.user_roles(user_id,role) values('28000600-0000-4000-8000-000000000001','professional') on conflict do nothing;
insert into public.professional_student_relationships(professional_user_id,student_user_id,status) values('28000600-0000-4000-8000-000000000001','28000600-0000-4000-8000-000000000002','active');
insert into public.account_preferences(user_id,preferences) values('28000600-0000-4000-8000-000000000002','{"profile":{"heightCm":170,"birthDate":"1990-01-01","goal":"build_muscle"},"privateSetting":"secret"}');
insert into public.bodyweight_entries(user_id,measured_on,weight_kg) values('28000600-0000-4000-8000-000000000002','2026-10-01',70),('28000600-0000-4000-8000-000000000002','2026-10-20',68.5);
insert into public.body_measurement_checkins(user_id,measured_on,measurements_cm,note) values('28000600-0000-4000-8000-000000000002','2026-10-20','{"chest":95}','Referência');
set local role authenticated;
select set_config('request.jwt.claim.sub','28000600-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select profile->>'heightCm'='170' and not profile ? 'privateSetting' and weight_history->0->>'weight_kg'='68.500' and jsonb_array_length(weight_history)=2 and measurements->0->'measurements_cm'->>'chest'='95' from public.professional_client_detail('28000600-0000-4000-8000-000000000002')),'linked professional sees profile and ordered history only');
select set_config('request.jwt.claim.sub','28000600-0000-4000-8000-000000000003',true);
select pg_temp.assert_true(not exists(select 1 from public.professional_client_detail('28000600-0000-4000-8000-000000000002')),'unlinked user cannot read profile');
reset role;
update public.professional_student_relationships set status='revoked' where professional_user_id='28000600-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','28000600-0000-4000-8000-000000000001',true);
select pg_temp.assert_true(not exists(select 1 from public.professional_client_detail('28000600-0000-4000-8000-000000000002')),'revoked professional cannot read profile');
rollback;
